const NAMES = {
  "party": "crossed-swords",
  "sword": "broadsword",
  "map": "treasure-map",
  "kingdom": "castle",
  "here": "position-marker",
  "fame": "laurels-trophy",
  "settings": "cog",
  "lever": "lever",
  "camp": "campfire",
  "campfire": "campfire",
  "crate": "knapsack",
  "quests": "scroll-unfurled",
  "scroll": "tied-scroll",
  "graveyard": "tombstone",
  "skull": "skull-crossed-bones",
  "stamina": "hourglass",
  "heart": "hearts",
  "heartHalf": "hearts",
  "heartEmpty": "hearts",
  "context": "magic-potion",
  "mana": "magic-potion",
  "coin": "two-coins",
  "chest": "open-treasure-chest",
  "waiting": "ringing-bell",
  "d20": "dice-twenty-faces-twenty",
  "d20one": "dice-twenty-faces-one",
  "book": "spell-book",
  "dragon": "dragon-head"
} as const

export type InkedName = keyof typeof NAMES

export const isInkedName = (name: string): name is InkedName => name in NAMES

// One icon at `size` px, filled with `color` (the theme's own), optionally
// turned by `turn` degrees about its centre (the rolling d20).
export function inkedSvg(name: InkedName, size: number, color: string, turn = 0): string {
  const rotate = turn === 0 ? '' : ` transform="rotate(${turn} 256 256)"`
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512" width="${size}" height="${size}"><path fill="${color}"${rotate} d="${PATHS[NAMES[name]] ?? ''}"/></svg>`
}
